# What a backend plugin exports -- TZ v4.2 §26.4, "экспортируют одну C ABI entry point".
#
# Hidden visibility is not enough on its own, and the difference is worth knowing: it
# governs the symbols this project compiles, while a plugin also links its codec library
# from a static archive, whose symbols arrive already compiled and default-visible. Measured
# on the first build of these modules: the x265 plugin exported 1318 symbols, all but one of
# them libx265's own. Two such modules in one process, or one beside a host that has its own
# copy of the same library, and which definition wins is decided by load order.
#
# So the export list is stated here rather than inferred. One name global, everything else
# local, whatever it was compiled from.
SVE_BACKEND_PLUGIN_V1 {
    global:
        sve_backend_plugin_v1;
    local:
        *;
};
